"""Make Webots run our controllers with the project's virtual environment.

By default Webots starts controllers with the system `python`, which can't
import the packages in `src/`. A `runtime.ini` next to each controller can
name another interpreter, but the path must be absolute: a relative one
crashes the whole of Webots R2025a (tested, see docs/design-log.md). So
the files are written here, from the interpreter running this code, and
kept out of git.
"""

import sys
from pathlib import Path

HEADER = """\
; Generated by make_world.py, not in git: Webots must run this controller with
; the project's virtual environment. Absolute on purpose: a relative path
; crashes Webots.
"""


def write_runtime_inis(controllers: Path, python: Path = Path(sys.executable)) -> list[Path]:
    """Write `runtime.ini` into every controller folder; return the files that changed."""
    text = f"{HEADER}[python]\nCOMMAND = {python.resolve().as_posix()}\n"
    changed = []
    for folder in sorted(p for p in controllers.iterdir() if p.is_dir()):
        if not (folder / f"{folder.name}.py").exists():
            continue  # not a Python controller
        ini = folder / "runtime.ini"
        if not ini.exists() or ini.read_text(encoding="utf-8") != text:
            ini.write_text(text, encoding="utf-8")
            changed.append(ini)
    return changed
